import csv
import json

def sum_by_category(filename):
    # Initialize a dictionary to store the sum of amounts by category
    sum_by_category = {}

    # Read the CSV file
    with open(filename, 'r') as file:
        reader = csv.DictReader(file)
        for row in reader:
            category = row['category']
            amount = float(row['amount'])

            # Add the amount to the corresponding category in the dictionary
            if category in sum_by_category:
                sum_by_category[category] += amount
            else:
                sum_by_category[category] = amount

    # Round the sums to 2 decimal places
    sum_by_category = {category: round(amount, 2) for category, amount in sum_by_category.items()}

    return sum_by_category

def main():
    filename = 'expenses_medium.csv'
    result = sum_by_category(filename)
    print(json.dumps({"sum_by_category": result}))

if __name__ == "__main__":
    main()

